import math

def expression(n):
    # E(n) = 3 * ((n+2)! + 1) / (2n - 1)
    if n < 0:
        return None # Should not happen based on problem statement

    denominator = 2 * n - 1

    # Check for division by zero, though for integer n >= 0, 2n-1 is never 0.
    if denominator == 0:
        return None

    numerator = 3 * (math.factorial(n + 2) + 1)

    return numerator / denominator

test_range = range(8) # n = 0, 1, ..., 7
results = {}

for n in test_range:
    result = expression(n)
    is_integer = result == int(result)
    results[n] = {
        "value": result,
        "is_integer": is_integer
    }

print("Results for n=0 to n=7:")
for n, res in results.items():
    print(f"n={n}: Value = {res['value']}, Integer = {res['is_integer']}")

